export const margin=(value:number|null,cost:number|null)=>value&&cost!==null?100*(value-cost)/value:null;
export const isOpen=(d:Deal)=>!['won','lost','paused'].includes(d.stage);
export function concerns(c:Customer,today=day(),st?:State){const r:string[]=[];if(c.status==='closed'||c.status==='prospect')return r;if(c.plan?.issueStatus==='open')r.push('Öppet kundärende: '+c.plan.issue);if(c.plan?.nextNeedDate&&plusDays(c.plan.nextNeedDate,-14)<=today)r.push('Planera inför nästa inköpsbehov');if(c.status==='risk')r.push(c.riskReason||'Manuellt markerad för omsorg');if(c.nextReview&&c.nextReview<today)r.push('Kunduppföljning försenad');if(c.expectedOrder&&c.expectedOrder<today)r.push('Förväntat återköp behöver stämmas av');if(c.lastContact&&plusDays(c.lastContact,c.reviewDays)<today)r.push('Länge sedan senaste kontakt');if(['active','growth','risk'].includes(c.status)){if(st&&!st.tasks.some(t=>t.customerId===c.id&&!t.done)&&!st.meetings.some(m=>m.customerId===c.id&&m.status==='planned'&&m.date>=today))r.push('Aktiv kund utan planerad aktivitet');else if(!st&&!c.nextReview&&!c.plan.nextDate)r.push('Nästa kundkontakt saknas');}return r;}
