  if(Object.prototype.hasOwnProperty.call(input,key))need(JSON.stringify(next[key])===JSON.stringify(old?.[key]??(key==='ownerProfileId'?'':[])),'Ansvarsprofil och ansvarshistorik ändras bara genom en granskad överföring.');
