   const profile=next.settings.sellerProfilesInitialized?sellerProfileForOwner(next.settings,row.owner):undefined;
   need(!next.settings.sellerProfilesInitialized||profile?.active&&next.settings.owners.includes(profile.legacyOwnerName),name==='customers'?'Välj en aktiv, granskad säljarprofil för den nya kundens ansvar.':'Välj en aktiv, granskad säljarprofil för nytt affärs- eller orderansvar.');
